CREATE TABLE software_signing_settings (id INTEGER PRIMARY KEY CHECK(id=1), software_signing_enabled INTEGER NOT NULL DEFAULT 0 CHECK(software_signing_enabled IN (0,1)), updated_at TEXT NOT NULL, updated_by TEXT NOT NULL);
INSERT INTO software_signing_settings VALUES(1,0,strftime('%Y-%m-%dT%H:%M:%fZ','now'),'migration');
CREATE TABLE software_contractor_config (version INTEGER PRIMARY KEY CHECK(version>0), values_json TEXT NOT NULL CHECK(json_valid(values_json)), created_at TEXT NOT NULL, created_by TEXT NOT NULL);
CREATE TABLE software_agreement_templates (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('msa','sow')), version INTEGER NOT NULL CHECK(version>0), text TEXT NOT NULL CHECK(length(CAST(text AS BLOB))<=102400), sha256 TEXT NOT NULL CHECK(length(sha256)=64), field_schema_version INTEGER NOT NULL DEFAULT 1 CHECK(field_schema_version=1), published_at TEXT NOT NULL, published_by TEXT NOT NULL, UNIQUE(kind,version));
ALTER TABLE software_offers ADD COLUMN agreement_details_json TEXT;
ALTER TABLE software_offers ADD COLUMN msa_template_id TEXT REFERENCES software_agreement_templates(id);
ALTER TABLE software_offers ADD COLUMN sow_template_id TEXT REFERENCES software_agreement_templates(id);
ALTER TABLE software_offers ADD COLUMN contractor_snapshot_json TEXT;
ALTER TABLE software_offers ADD COLUMN recipient_email_snapshot TEXT;
ALTER TABLE software_offers ADD COLUMN reused_msa_id TEXT REFERENCES software_agreements(id);
CREATE TABLE software_agreement_clients (id TEXT PRIMARY KEY, recipient_email TEXT NOT NULL, legal_name TEXT NOT NULL, legal_name_key TEXT NOT NULL, entity_type TEXT NOT NULL, jurisdiction TEXT NOT NULL, business_address TEXT NOT NULL, notice_email TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(recipient_email,legal_name_key,entity_type,jurisdiction));
CREATE TABLE software_agreements (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('msa','sow')), offer_id TEXT REFERENCES software_offers(id), request_id TEXT NOT NULL, client_id TEXT NOT NULL REFERENCES software_agreement_clients(id), template_id TEXT NOT NULL REFERENCES software_agreement_templates(id), msa_id TEXT REFERENCES software_agreements(id), sow_number TEXT, status TEXT NOT NULL CHECK(status IN ('review','client_signed','executed','abandoned')), canonical_text TEXT NOT NULL CHECK(length(CAST(canonical_text AS BLOB))<=262144), text_sha256 TEXT NOT NULL CHECK(length(text_sha256)=64), render_version INTEGER NOT NULL DEFAULT 1 CHECK(render_version=1), values_json TEXT NOT NULL CHECK(json_valid(values_json)), attachment_manifest_json TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL, client_signed_at TEXT, executed_at TEXT, effective_on TEXT NOT NULL, ended_at TEXT, retain_until TEXT, legal_hold INTEGER NOT NULL DEFAULT 0 CHECK(legal_hold IN (0,1)), terminated_at TEXT, abandoned_at TEXT, abandoned_reason TEXT, review_session_hash TEXT NOT NULL);
CREATE UNIQUE INDEX software_agreements_sow_offer ON software_agreements(offer_id) WHERE kind='sow' AND status<>'abandoned';
CREATE UNIQUE INDEX software_agreements_pending_msa ON software_agreements(client_id,template_id) WHERE kind='msa' AND status IN ('review','client_signed');
CREATE TABLE software_agreement_signatures (id TEXT PRIMARY KEY, agreement_id TEXT NOT NULL REFERENCES software_agreements(id), party TEXT NOT NULL CHECK(party IN ('client','contractor')), typed_name TEXT NOT NULL, title TEXT NOT NULL, consent_text TEXT NOT NULL, authority_text TEXT NOT NULL, consent_version TEXT NOT NULL, consent_at TEXT NOT NULL, signed_at TEXT NOT NULL, document_sha256 TEXT NOT NULL, session_token_hash TEXT, owner_subject TEXT, verified_email TEXT NOT NULL, verified_at TEXT NOT NULL, intent_text TEXT NOT NULL, document_list_json TEXT NOT NULL, receipt_id TEXT NOT NULL, ip_address TEXT NOT NULL, user_agent TEXT NOT NULL, UNIQUE(agreement_id,party));
CREATE TABLE software_agreement_challenges (id TEXT PRIMARY KEY, purpose TEXT NOT NULL CHECK(purpose IN ('agreement','archive')), offer_id TEXT REFERENCES software_offers(id), link_hash TEXT, recipient_email TEXT NOT NULL, code_hash TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 5), issued_at TEXT NOT NULL, expires_at TEXT NOT NULL, used_at TEXT);
CREATE INDEX software_agreement_challenges_scope ON software_agreement_challenges(purpose,recipient_email,offer_id,issued_at);
CREATE TABLE software_agreement_sessions (token_hash TEXT PRIMARY KEY, purpose TEXT NOT NULL CHECK(purpose IN ('agreement','archive')), offer_id TEXT REFERENCES software_offers(id), link_hash TEXT, recipient_email TEXT NOT NULL, challenge_id TEXT NOT NULL REFERENCES software_agreement_challenges(id), verified_at TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT, csrf_nonce TEXT NOT NULL);
CREATE TABLE software_agreement_artifacts (agreement_id TEXT PRIMARY KEY REFERENCES software_agreements(id), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','rendering','ready','failed')), attempt_id TEXT, attempted_at TEXT, pdf_key TEXT, pdf_sha256 TEXT, certificate_key TEXT, certificate_sha256 TEXT, manifest_json TEXT, bytes INTEGER, renderer_version TEXT, error_code TEXT CHECK(error_code IS NULL OR error_code IN ('render','storage','readback')), ready_at TEXT);
CREATE TABLE software_agreement_deliveries (agreement_id TEXT NOT NULL REFERENCES software_agreements(id), recipient_role TEXT NOT NULL CHECK(recipient_role IN ('client','contractor')), email TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sending','sent','failed')), attempt_id TEXT, attempted_at TEXT, sent_at TEXT, alternate_delivered_at TEXT, alternate_method TEXT, PRIMARY KEY(agreement_id,recipient_role));
CREATE TABLE software_agreement_events (id TEXT PRIMARY KEY, agreement_id TEXT REFERENCES software_agreements(id), offer_id TEXT, action TEXT NOT NULL CHECK(action IN ('template-published','code-issued','code-rejected','verified','reviewed','client-signed','countersigned','abandoned','artifact-ready','delivery-failed','copy-delivered','hold-changed','retention-deleted','external-signature-recorded')), actor TEXT NOT NULL, occurred_at TEXT NOT NULL, reason TEXT);
ALTER TABLE software_projects ADD COLUMN agreement_id TEXT REFERENCES software_agreements(id);
ALTER TABLE software_projects ADD COLUMN signature_source TEXT CHECK(signature_source IN ('website','external'));
ALTER TABLE software_projects ADD COLUMN external_signature_details_json TEXT;
CREATE TRIGGER software_agreement_templates_immutable BEFORE UPDATE ON software_agreement_templates BEGIN SELECT RAISE(ABORT,'Immutable template'); END;
CREATE TRIGGER software_contractor_config_immutable BEFORE UPDATE ON software_contractor_config BEGIN SELECT RAISE(ABORT,'Immutable config'); END;
CREATE TRIGGER software_agreement_signatures_immutable BEFORE UPDATE ON software_agreement_signatures BEGIN SELECT RAISE(ABORT,'Immutable signature'); END;
CREATE TRIGGER software_agreements_signed_immutable BEFORE UPDATE OF canonical_text,text_sha256,values_json,template_id,client_id,attachment_manifest_json,effective_on,offer_id,msa_id ON software_agreements WHEN OLD.status<>'review' BEGIN SELECT RAISE(ABORT,'Immutable signed agreement'); END;
CREATE TABLE software_agreement_attachments (id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES owner_requests(id), filename TEXT NOT NULL, version TEXT NOT NULL, document_date TEXT NOT NULL, object_key TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL CHECK(length(sha256)=64 AND sha256 NOT GLOB '*[^a-f0-9]*'), bytes INTEGER NOT NULL CHECK(bytes>0 AND bytes<=10485760), created_at TEXT NOT NULL, created_by TEXT NOT NULL);
CREATE TRIGGER software_agreement_clients_immutable BEFORE UPDATE ON software_agreement_clients BEGIN SELECT RAISE(ABORT,'Immutable identity'); END;
ALTER TABLE software_agreements ADD COLUMN archive_closed_at TEXT;
CREATE TABLE software_agreement_retention_receipts (id TEXT PRIMARY KEY, agreement_id TEXT NOT NULL, text_sha256 TEXT NOT NULL, deleted_at TEXT NOT NULL, manifest_sha256 TEXT NOT NULL);
CREATE TRIGGER software_agreement_cleanup_lock BEFORE UPDATE OF ended_at,retain_until,legal_hold,terminated_at ON software_agreements WHEN OLD.archive_closed_at IS NOT NULL BEGIN SELECT RAISE(ABORT,'Archive cleanup is reserved'); END;
ALTER TABLE software_projects ADD COLUMN start_details_json TEXT;
CREATE TABLE software_agreement_notices (id TEXT PRIMARY KEY, agreement_id TEXT NOT NULL REFERENCES software_agreements(id), client_id TEXT NOT NULL REFERENCES software_agreement_clients(id), business_address TEXT NOT NULL, notice_email TEXT NOT NULL, recorded_at TEXT NOT NULL, UNIQUE(agreement_id));
CREATE TRIGGER software_agreement_notices_immutable BEFORE UPDATE ON software_agreement_notices BEGIN SELECT RAISE(ABORT,'Immutable notice'); END;
CREATE TABLE software_agreement_notifications (agreement_id TEXT NOT NULL REFERENCES software_agreements(id), kind TEXT NOT NULL CHECK(kind IN ('signature-receipt','countersign-notice')), email TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sending','sent','failed')), attempt_id TEXT, attempted_at TEXT, sent_at TEXT, PRIMARY KEY(agreement_id,kind));
